cells={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# all square/L tiles
tiles=[]
for r in range(6):
 for c in range(6):
  box={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if box<=cells: tiles.append(('S',box,(r,c)))
  for missing in box:
   t=box-{missing}
   if t<=cells: tiles.append(('L',t,(r,c,missing)))
sol=[]
def dfs(rem, chosen):
 if not rem:
  sol.append(chosen);return
 x=min(rem,key=lambda a:sum(x in t[1] for t in tiles))
 for t in tiles:
  if x in t[1] and t[1]<=rem:
   dfs(rem-t[1],chosen+[t])
dfs(cells,[])
len(sol), sol[:3]

